-- =============================================================================
-- 492 — LE CAHIER D'EXERCICES DE 4E (partie 11)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/4e/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 492 --niveau 4e --fichiers svt.jumelles --suffixe 11 > supabase/contenu/492_exercices_4e_11.sql
--
-- 75 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   svt.jumelles            75 exercices · 25 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('ffe5417e-2dd1-5894-8bc7-22ba4dbc6393'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Une hydre qui bourgeonne","competence":"observer-schema","situation":"Une hydre est un petit animal d’eau douce. Ce schéma la montre vue de côté, au moment où elle se reproduit.","documents":[{"id":"hydre","type":"schema","titre":"Une hydre d’eau douce","largeur":340,"hauteur":240,"elements":[{"forme":"rect","x":140,"y":70,"l":36,"h":120,"arrondi":14,"teinte":"vert","motif":"clair"},{"forme":"ellipse","cx":158,"cy":198,"rx":32,"ry":9,"teinte":"vert","motif":"plein"},{"forme":"ligne","de":[146,70],"a":[122,38],"teinte":"encre"},{"forme":"ligne","de":[152,70],"a":[140,30],"teinte":"encre"},{"forme":"ligne","de":[158,70],"a":[158,26],"teinte":"encre"},{"forme":"ligne","de":[164,70],"a":[176,30],"teinte":"encre"},{"forme":"ligne","de":[170,70],"a":[194,38],"teinte":"encre"},{"forme":"ellipse","cx":198,"cy":132,"rx":22,"ry":28,"teinte":"vert","motif":"clair","id":"z1","zone":true},{"forme":"ligne","de":[192,106],"a":[186,92],"teinte":"encre"},{"forme":"ligne","de":[204,106],"a":[212,92],"teinte":"encre"},{"forme":"texte","x":158,"y":224,"texte":"Hydre adulte (parent)","taille":"petit","ancre":"milieu"}]}],"questions":[{"enonce":"Touche le jeune individu en train de se former sur le parent.","aide":"Il est plus petit et accroché sur le côté du corps de l’hydre.","type":"zone","document":"hydre","multiple":false},{"enonce":"Range les étapes du bourgeonnement dans l’ordre.","aide":"Le bourgeon doit d’abord apparaître et grandir.","type":"ordre","items":[{"id":"a","texte":"Un nouvel individu vit de façon indépendante"},{"id":"b","texte":"Le bourgeon se détache du parent"},{"id":"c","texte":"Un bourgeon se forme sur le parent"},{"id":"d","texte":"Le bourgeon grandit et développe des tentacules"}]},{"enonce":"Que dire des gènes du bourgeon par rapport à ceux du parent ?","aide":"Y a-t-il ici un deuxième parent, des gamètes, une fécondation ?","type":"choix","options":[{"id":"a","texte":"Il a la moitié des gènes du parent, comme le ferait un gamète de l’hydre"},{"id":"b","texte":"Ses gènes sont tirés au hasard parmi ceux de toute la population d’hydres"},{"id":"c","texte":"Il a des gènes d’un deuxième parent, rencontré lors de la reproduction"},{"id":"d","texte":"Ils sont identiques : le bourgeon est un clone génétique de l’hydre parent"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"C’est le **bourgeon**, un futur individu qui grandit sur son parent."},{"cle":{"type":"ordre","ids":["c","d","b","a"]},"explication":"Le bourgeon **apparaît, grandit, se détache**, puis le nouvel individu vit seul."},{"cle":{"type":"choix","ids":["d"]},"explication":"Sans gamète ni fécondation, le descendant est un **clone** : génétiquement identique à son parent."}]$ex$::jsonb),
  ('ffe5417e-2dd1-5894-8bc7-22ba4dbc6393'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le catalogue du jardinier","competence":"analyser-document","situation":"Le jardinier d’un lycée multiplie ses plantes sans les semer. Dans son catalogue, il décrit ce qu’il replante pour chaque espèce.","documents":[{"id":"cat","type":"tableau","titre":"Le catalogue du jardinier","colonnes":["Plante","Ce que le jardinier replante"],"lignes":[["Tulipe","Un petit « oignon » prélevé au pied de la plante"],["Pomme de terre","Un morceau de la réserve renflée, avec un œil"],["Iris","Un morceau de tige souterraine horizontale"],["Fraisier","Un jeune plant né au bout d’une tige rampante"]],"enteteLignes":true,"source":"Catalogue imaginé pour l’exercice"}],"questions":[{"enonce":"Associe chaque plante à son organe de multiplication.","aide":"Le stolon rampe à la surface ; le rhizome est souterrain ; le tubercule est une réserve renflée.","type":"association","gauche":[{"id":"g0","texte":"Tulipe"},{"id":"g1","texte":"Pomme de terre"},{"id":"g2","texte":"Iris"},{"id":"g3","texte":"Fraisier"}],"droite":[{"id":"d0","texte":"Stolon"},{"id":"d1","texte":"Bulbe"},{"id":"d2","texte":"Rhizome"},{"id":"d3","texte":"Tubercule"}]},{"enonce":"Le jardinier plante dix morceaux d’un même tubercule. Que dire des dix plantes obtenues ?","aide":"Il n’y a ni fleur, ni graine, ni fécondation.","type":"choix","options":[{"id":"a","texte":"Elles sont génétiquement identiques entre elles et à la plante mère"},{"id":"b","texte":"Elles sont identiques entre elles, mais pas à la plante mère"},{"id":"c","texte":"Elles ont la moitié des gènes de la plante mère"},{"id":"d","texte":"Elles sont toutes différentes"}],"multiple":false},{"enonce":"Un fraisier produit 5 stolons, chacun donnant un nouveau fraisier. Chaque nouveau fraisier en produit à son tour 5. Combien de fraisiers y a-t-il au total, parent compris, après ces deux générations ?","aide":"Compte le parent, puis ses 5 jeunes, puis les jeunes de chacun.","type":"nombre","unite":"fraisiers"},{"enonce":"Le jardinier veut obtenir un fraisier résistant à une nouvelle maladie. Que lui conseiller ?","aide":"Pour trouver une résistance, il faut de la diversité.","type":"choix","options":[{"id":"a","texte":"Changer d’espèce de plante, car aucun fraisier ne pourra jamais résister à une maladie"},{"id":"b","texte":"Multiplier par stolons : les plants seront tous différents, donc certains résisteront"},{"id":"c","texte":"Multiplier par stolons : tous les plants résisteront, car ils sont identiques au parent"},{"id":"d","texte":"Semer des graines issues de fleurs : les plants seront différents, certains résisteront"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g3":"d0","g0":"d1","g2":"d2","g1":"d3"}},"explication":"La tulipe se multiplie par **bulbes**, la pomme de terre par **tubercules**, l’iris par **rhizomes**, le fraisier par **stolons**."},{"cle":{"type":"choix","ids":["a"]},"explication":"La multiplication végétative donne des **clones**."},{"cle":{"type":"nombre","valeur":31,"tolerance":0},"affichage":"31 fraisiers","explication":"1 + 5 + 5 × 5 = **31 fraisiers**."},{"cle":{"type":"choix","ids":["d"]},"explication":"Les stolons donnent des **clones**, tous sensibles ; la reproduction sexuée crée de la **diversité**."}]$ex$::jsonb),
  ('ffe5417e-2dd1-5894-8bc7-22ba4dbc6393'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Clones : vitesse et danger","competence":"analyser-document","situation":"Un rosier est envahi par des pucerons. Un naturaliste compte la population chaque semaine. Un second document rappelle une catastrophe agricole du XIXe siècle.","documents":[{"id":"puc","type":"graphique","forme":"courbe","titre":"Pucerons sur un rosier","categories":["0","1","2","3","4","5"],"series":[{"nom":"Pucerons","valeurs":[10,20,40,80,160,320],"teinte":"vert"}],"axeY":{"titre":"Nombre de pucerons","min":0,"max":320,"pas":40},"axeX":{"titre":"Semaines"},"valeurs":false},{"id":"irlande","type":"texte","genre":"article","titre":"L’Irlande et sa pomme de terre","blocs":["Au milieu du XIXe siècle, presque toute l’Irlande cultivait la même variété de pomme de terre, multipliée par tubercules. Tous les plants étaient donc des clones.","En 1845, le mildiou, un champignon microscopique, atteint les champs : presque toutes les plantes tombent malades et les récoltes pourrissent. La famine qui suit fait environ un million de morts et pousse des centaines de milliers d’Irlandais à émigrer."],"source":"Texte écrit pour l’exercice, chiffres arrondis"}],"questions":[{"enonce":"Par combien la population de pucerons est-elle multipliée chaque semaine ?","aide":"Compare le nombre de pucerons d’une semaine à la suivante.","type":"nombre"},{"enonce":"Si la population continue ainsi, combien y aura-t-il de pucerons à la semaine 7 ?","aide":"Part de la semaine 5 et double deux fois.","type":"nombre","unite":"pucerons"},{"enonce":"Touche, dans l’article, le mot qui désigne l’organe par lequel la pomme de terre se multiplie.","aide":"C’est une réserve souterraine renflée.","type":"zone","document":"irlande","multiple":false},{"enonce":"Pourquoi le mildiou a-t-il ravagé presque tous les champs irlandais ?","aide":"Que signifie « tous des clones » face à une maladie ?","type":"choix","options":[{"id":"a","texte":"Le mildiou ne touche que les plantes diverses, et jamais les clones cultivés"},{"id":"b","texte":"Les plants étaient trop variés pour pouvoir être soignés de la même façon"},{"id":"c","texte":"Tous les plants étaient des clones, donc tous aussi sensibles à la maladie"},{"id":"d","texte":"Les plants étaient issus de graines, donc tous différents les uns des autres"}],"multiple":false},{"enonce":"À l’automne, les pucerons passent à la reproduction sexuée et pondent des œufs résistants. Quel est l’intérêt ?","aide":"Pense à l’imprévu : le froid, de nouveaux parasites.","type":"choix","options":[{"id":"a","texte":"Produire des individus différents et passer l’hiver sous forme d’œufs résistants"},{"id":"b","texte":"Se passer de tout partenaire pour se reproduire, même en hiver, comme les clones"},{"id":"c","texte":"Produire des clones identiques au parent, tous adaptés au froid de l’hiver"},{"id":"d","texte":"Produire davantage d’individus et plus vite que pendant toute la belle saison"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2","explication":"Elle passe de 10 à 20, à 40, à 80 : elle est multipliée par **2** chaque semaine."},{"cle":{"type":"nombre","valeur":1280,"tolerance":0},"affichage":"1280 pucerons","explication":"Semaine 5 : 320, semaine 6 : 640, semaine 7 : **1 280**. Sans partenaire à chercher, les pucerons colonisent vite."},{"cle":{"type":"zone","ids":["m19"]},"explication":"La pomme de terre se multiplie par **tubercules**, sans fécondation."},{"cle":{"type":"choix","ids":["c"]},"explication":"Sans **diversité génétique**, la maladie frappe tous les plants de la même façon : c’est l’inconvénient majeur de la reproduction asexuée."},{"cle":{"type":"choix","ids":["a"]},"explication":"La reproduction sexuée prépare l’**imprévu** : diversité des descendants et œufs résistants à la mauvaise saison."}]$ex$::jsonb),
