   $ex${"titre":"Le lac de Valmont","competence":"analyser-texte","situation":"Un article imaginaire décrit ce qui change autour d’un lac. Chaque paragraphe décrit une pression différente sur la biodiversité.","documents":[{"id":"article","type":"texte","genre":"article","titre":"Le lac de Valmont en danger","auteur":"Article imaginé pour l’exercice","blocs":["En vingt ans, la forêt qui bordait le lac a laissé place à des lotissements et à un grand parking.","Les pêcheurs prélèvent chaque année plus de brochets que le lac ne peut en renouveler : les prises diminuent.","Une plante aquatique venue d’Amérique du Sud, relâchée par un aquariophile, recouvre désormais la moitié de l’eau.","Enfin, les engrais des champs voisins, entraînés par la pluie, se retrouvent dans l’eau du lac."]}],"questions":[{"enonce":"Associe chaque observation à la pression qu’elle illustre.","aide":"Relis chaque paragraphe : que se passe-t-il ?","type":"association","gauche":[{"id":"g0","texte":"Des lotissements remplacent la forêt"},{"id":"g1","texte":"Plus de brochets pêchés que le lac n’en renouvelle"},{"id":"g2","texte":"Une plante venue d’Amérique du Sud recouvre l’eau"},{"id":"g3","texte":"Les engrais des champs arrivent dans le lac"}],"droite":[{"id":"d0","texte":"Destruction des habitats"},{"id":"d1","texte":"Espèce invasive"},{"id":"d2","texte":"Pollution"},{"id":"d3","texte":"Surexploitation"}]},{"enonce":"Touche, dans le texte, le mot qui désigne l’espèce invasive.","aide":"Elle vient d’Amérique du Sud et recouvre l’eau.","type":"zone","document":"article","multiple":false},{"enonce":"Combien de pressions différentes l’article décrit-il ?","aide":"Compte les paragraphes : chacun en décrit une.","type":"nombre","unite":"pressions"},{"enonce":"Ces pressions agissent en même temps sur le lac. Quel en est le résultat ?","aide":"Elles ne s’additionnent pas à part : elles agissent ensemble.","type":"choix","options":[{"id":"a","texte":"Elles s’annulent entre elles"},{"id":"b","texte":"Elles ne touchent que les poissons"},{"id":"c","texte":"Leurs effets se cumulent"},{"id":"d","texte":"Seule la plus forte compte"}],"multiple":false}]}$ex$::jsonb,
