   $ex${"titre":"Des journées qui s’allongent","competence":"lire-graphique","situation":"À Paris, la durée du jour change au fil de l’année. Le graphique la donne à quatre dates : les deux équinoxes et les deux solstices.","documents":[{"id":"jour","type":"graphique","forme":"courbe","titre":"Durée du jour à Paris","categories":["21 mars","21 juin","23 sept.","21 déc."],"series":[{"nom":"Durée du jour","valeurs":[12,16,12,8],"teinte":"ambre"}],"axeY":{"titre":"Durée du jour","unite":"h","min":0,"max":20,"pas":4},"axeX":{"titre":"Date"},"valeurs":false,"source":"Valeurs arrondies"}],"questions":[{"enonce":"Quelle est la durée du jour à Paris le 21 juin ?","aide":"Lis la hauteur du point « 21 juin ».","type":"nombre","unite":"h"},{"enonce":"De combien d’heures le jour est-il plus court le 21 décembre que le 21 juin ?","aide":"Soustrais : 16 − 8.","type":"nombre","unite":"h"},{"enonce":"Touche les deux dates où le jour et la nuit durent autant (12 h chacun).","aide":"Cherche les points à 12 h.","type":"zone","document":"jour","multiple":true},{"enonce":"Quelle est la cause de ces variations de durée du jour ?","aide":"Ce ne sont pas les distances qui font les saisons.","type":"choix","options":[{"id":"a","texte":"La distance Terre–Soleil, plus courte en été"},{"id":"b","texte":"Les mouvements de la Lune"},{"id":"c","texte":"La vitesse de rotation de la Terre, plus rapide en été"},{"id":"d","texte":"L’inclinaison de 23,5° de l’axe de rotation de la Terre"}],"multiple":false},{"enonce":"Le 21 décembre, que se passe-t-il dans l’hémisphère sud ?","aide":"Quand l’hémisphère nord est penché loin du Soleil, l’autre l’est vers lui.","type":"choix","options":[{"id":"a","texte":"La durée du jour y est de 12 h"},{"id":"b","texte":"Il y fait nuit toute la journée"},{"id":"c","texte":"Les jours y sont les plus longs : c’est l’été"},{"id":"d","texte":"Les jours y sont les plus courts : c’est l’hiver"}],"multiple":false}]}$ex$::jsonb,
