   $ex${"titre":"Le traitement qui ne marche plus","competence":"raisonner","situation":"Dans le corps d’Inès, un million de bactéries causent une infection. Un antibiotique tue les bactéries sensibles. Quelques bactéries portent, par hasard, une mutation qui les rend résistantes : elle existait avant le traitement.","documents":[{"id":"bacteries","type":"tableau","titre":"Les bactéries d’Inès","colonnes":["Moment","Sensibles","Résistantes"],"lignes":[["Avant le traitement","999 990","10"],["Juste après l’antibiotique","0","10"],["Après multiplication","0","10 000"]],"enteteLignes":true,"source":"Chiffres inventés pour l’exercice"}],"questions":[{"enonce":"Combien de bactéries survivent à l’antibiotique ?","aide":"Lis la ligne « Juste après l’antibiotique ».","type":"nombre","unite":"bactéries"},{"enonce":"Touche le nombre de bactéries résistantes après multiplication.","aide":"Lis la dernière ligne, colonne « Résistantes ».","type":"zone","document":"bacteries","multiple":false},{"enonce":"Par quel nombre les bactéries résistantes ont-elles été multipliées ?","aide":"Divise 10 000 par 10.","type":"nombre","unite":"fois"},{"enonce":"D’où vient la résistance ?","aide":"Relis la situation : la mutation existait avant le traitement.","type":"choix","options":[{"id":"a","texte":"D’une mutation présente avant le traitement : l’antibiotique ne fait que trier"},{"id":"b","texte":"L’antibiotique a fabriqué la mutation chez les bactéries pour qu’elles survivent"},{"id":"c","texte":"Elle vient d’Inès elle-même : son organisme a rendu les bactéries résistantes"},{"id":"d","texte":"Les bactéries ont décidé de résister en changeant leur fonctionnement à volonté"}],"multiple":false},{"enonce":"Range les quatre temps du raisonnement de la sélection naturelle.","aide":"Variation, compétition, survie, fréquence.","type":"ordre","items":[{"id":"a","texte":"Les individus présentent des variations héréditaires"},{"id":"b","texte":"Les mieux adaptés survivent et se reproduisent davantage"},{"id":"c","texte":"Leurs caractères deviennent plus fréquents, génération après génération"},{"id":"d","texte":"Ils produisent plus de descendants que le milieu ne peut en nourrir : il y a compétition"}]}]}$ex$::jsonb,
