 salée"}],"multiple":false},{"enonce":"Classe chaque remède.","aide":"Certains remèdes économisent l’eau, d’autres évitent de la polluer.","type":"categories","categories":[{"id":"c0","texte":"Réduire les prélèvements"},{"id":"c1","texte":"Protéger la qualité de l’eau"}],"items":[{"id":"i0","texte":"Passer au goutte-à-goutte"},{"id":"i1","texte":"Interdire les pesticides autour des captages"},{"id":"i2","texte":"Protéger les zones de captage"},{"id":"i3","texte":"Réparer les fuites du réseau"}]}]}$ex$::jsonb,
